/**
 * PAINT (P08/P11): the one file a reader needs before the first coloured map — the status index (BCSI v2, unchanged:
 * `decodeStatusIndex`), the FLOW paint (which donor panel speaks for each section, the panels' members, the basins'
 * stations) and (T54) the NO-ACCESS rows (`access.ts`: the map's fourth colour and the Regulations tab's banner).
 * Format `paint/4`, written by `pipeline/deliver/release/paint.py`; that module's docstring is the layout and
 * `paint.fixture.ts` (generated by pipeline/tests/test_release.py) holds this decoder to the Python one.
 *
 * Decoded ONCE into arrays; a section's panel is a binary search over the runs (MINIMAL-PACKAGING §3 A4).
 * `flow-area/1` (the panel target areas, one per section in the same order) is a separate file, read with Conditions;
 * `access/1` (the gentler access tiers: permit-only land, reserves, private land) is another, read with a page.
 *
 * THE STATUS CARRIES THE ACCESS: `status.access` is this paint's no-access table, so the one colouring pathway (the
 * status channel's `profileLabel`) draws the fourth colour from the same file, with no second feed.
 */
import { accessOf, ACCESS_TIERS, type AccessArea, type SectionAccess } from "./access";
import { decodeStatusIndex, type StatusIndex } from "./statusIndex";
import type { RecordYears } from "./trust";

export class PaintError extends Error {}

export interface PanelMember {
  panel: number; ord: number; station: string; role: "up" | "down";
  /** Its record per quantity (paint/4, T110): read with `recordYears` for the quantity shown. */
  areaKm2: number; years: RecordYears; regulated: boolean; sameRiver: boolean;
  /** The section's own gauge, which may lead the answer: its rank, 0 not (paint/2; `Contribution.lead`). */
  lead: number;
}
export interface BasinMember { basin: string; station: string; areaKm2: number | null; years: RecordYears }

export interface Paint {
  /** The day's status index, carrying this paint's no-access table as `access`. */
  status: StatusIndex;
  /** (T54) The no-access rows: the sections the fourth colour and the banner speak for. */
  access: SectionAccess;
  stations: readonly string[];
  /** Section runs: `starts[i]`..`starts[i] + counts[i] - 1` speak through panel `panels[i]`. Sorted by start. */
  runs: { starts: Uint32Array; counts: Uint32Array; panels: Uint32Array };
  /** Every section with a panel, in sid order (the order flow-area's values follow). */
  sectionCount: number;
  members: readonly PanelMember[];
  basins: readonly BasinMember[];
  /** The panel speaking for a section, or null (binary search over the runs). */
  panelOf(sid: number): number | null;
}

class Reader {
  constructor(readonly b: Uint8Array, public i: number) {}
  fail(why: string): never { throw new PaintError(`paint: ${why} at byte ${this.i}`); }
  byte(): number { return this.i < this.b.length ? this.b[this.i++]! : this.fail("truncated"); }
  uv(): number {
    let n = 0, mul = 1, c: number;
    do { c = this.byte(); n += (c & 0x7f) * mul; mul *= 128; } while (c & 0x80);
    return n;
  }
  u32(): number { const v = new DataView(this.b.buffer, this.b.byteOffset + this.i, 4).getUint32(0, true); this.i += 4; return v; }
  u16(): number { const v = new DataView(this.b.buffer, this.b.byteOffset + this.i, 2).getUint16(0, true); this.i += 2; return v; }
  f64(): number { const v = new DataView(this.b.buffer, this.b.byteOffset + this.i, 8).getFloat64(0, true); this.i += 8; return v; }
  bytes(n: number): Uint8Array { if (this.i + n > this.b.length) this.fail("truncated"); const v = this.b.subarray(this.i, this.i + n); this.i += n; return v; }
}

const utf8 = (b: Uint8Array): string => {
  // Hermes has no TextDecoder; station ids and basin codes are ASCII, but decode UTF-8 properly anyway
  let s = "";
  for (let i = 0; i < b.length;) {
    const c = b[i++]!;
    if (c < 0x80) s += String.fromCharCode(c);
    else if (c < 0xe0) s += String.fromCharCode(((c & 0x1f) << 6) | (b[i++]! & 0x3f));
    else if (c < 0xf0) s += String.fromCharCode(((c & 0x0f) << 12) | ((b[i++]! & 0x3f) << 6) | (b[i++]! & 0x3f));
    else {
      const cp = ((c & 0x07) << 18) | ((b[i++]! & 0x3f) << 12) | ((b[i++]! & 0x3f) << 6) | (b[i++]! & 0x3f);
      s += String.fromCodePoint(cp);
    }
  }
  return s;
};

/** An access half (paint/3's and paint/4's, or the `access/1` file's): its areas, then three columns — sid gaps, areas, permille. */
function readAccess(r: Reader): SectionAccess {
  const areas: AccessArea[] = [];
  for (let i = 0, m = r.uv(); i < m; i++) {
    const t = r.uv();
    const tier = ACCESS_TIERS[t] ?? r.fail(`access tier ${t}`);
    areas.push({ tier, name: utf8(r.bytes(r.uv())) });
  }
  const n = r.uv();
  const sids = new Uint32Array(n), area = new Uint32Array(n), permille = new Uint16Array(n);
  for (let i = 0, s = 0; i < n; i++) { s += r.uv(); sids[i] = s; }
  for (let i = 0; i < n; i++) area[i] = r.uv();
  for (let i = 0; i < n; i++) permille[i] = r.uv();
  try {
    return accessOf(areas, sids, area, permille);
  } catch (e) {
    return r.fail((e as Error).message);
  }
}

export function decodePaint(bytes: Uint8Array, expectHandles: string | null, expectReach: string | null = null): Paint {
  if (bytes[0] !== 0x42 || bytes[1] !== 0x43 || bytes[2] !== 0x50 || bytes[3] !== 0x54) throw new PaintError("paint: not a paint file");
  // paint/2 added each member's `lead`, paint/3 the access half, paint/4 the record per quantity (T110): another
  // version is refused here
  if (bytes[4] !== 4) throw new PaintError(`paint: version ${bytes[4]} is not 4`);
  const r = new Reader(bytes, 5);
  const n = r.u32();
  const status = decodeStatusIndex(r.bytes(n), expectHandles, expectReach);
  const ln = r.u32();
  const stations = ln ? utf8(r.bytes(ln)).split("\n") : [];
  const nr = r.uv();
  const starts = new Uint32Array(nr), counts = new Uint32Array(nr), panels = new Uint32Array(nr);
  let end = 0, sections = 0;
  for (let i = 0; i < nr; i++) {
    starts[i] = end + r.uv(); counts[i] = r.uv(); panels[i] = r.uv();
    end = starts[i]! + counts[i]!; sections += counts[i]!;
  }
  const members: PanelMember[] = [];
  let pid = 0;
  for (let i = 0, m = r.uv(); i < m; i++) {
    pid += r.uv();
    const ord = r.uv(), si = r.uv(), role = r.uv(), area = r.uv(), discharge = r.uv(), level = r.uv(), reg = r.uv(),
          same = r.uv(), lead = r.uv();
    members.push({ panel: pid, ord, station: stations[si] ?? r.fail(`station ${si}`), role: role ? "down" : "up",
                   areaKm2: area / 1000, years: { discharge, level }, regulated: reg === 1, sameRiver: same === 1,
                   lead });
  }
  const basins: BasinMember[] = [];
  for (let i = 0, m = r.uv(); i < m; i++) {
    const basin = utf8(r.bytes(r.u16()));
    const si = r.uv(), has = r.uv();
    const areaKm2 = has ? r.f64() : null;
    const discharge = r.uv(), level = r.uv();
    basins.push({ basin, station: stations[si] ?? r.fail(`station ${si}`), areaKm2, years: { discharge, level } });
  }
  const access = readAccess(r);
  if (r.i !== bytes.length) throw new PaintError(`paint: ${bytes.length - r.i} trailing bytes`);
  const panelOf = (sid: number): number | null => {
    let lo = 0, hi = nr - 1;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1, s = starts[mid]!;
      if (sid < s) hi = mid - 1;
      else if (sid >= s + counts[mid]!) lo = mid + 1;
      else return panels[mid]!;
    }
    return null;
  };
  // the status carries the access (module comment): the index's own methods, bound, beside it
  const withAccess: StatusIndex = {
    handles: status.handles, reachDigest: status.reachDigest, sections: status.sections, waters: status.waters,
    profiles: status.profiles, access,
    codeOn: (s, on) => status.codeOn(s, on), profileOf: (s) => status.profileOf(s),
    profileCodeOn: (p, on) => status.profileCodeOn(p, on), waterCodeOn: (i, on) => status.waterCodeOn(i, on),
  };
  return { status: withAccess, access, stations, runs: { starts, counts, panels }, sectionCount: sections, members,
           basins, panelOf };
}

/**
 * `access/1` (T54): the gentler access tiers — permit-only land, reserves, private land — a Regulations page notes.
 * Held to the release's section handles, like `lakes/1`.
 */
export function decodeAccessFile(bytes: Uint8Array, expectHandles: string | null): SectionAccess {
  if (bytes[0] !== 0x42 || bytes[1] !== 0x43 || bytes[2] !== 0x41 || bytes[3] !== 0x58 || bytes[4] !== 1)
    throw new PaintError("access: not an access/1 file");
  const r = new Reader(bytes, 5);
  let handles = "";
  for (const b of r.bytes(8)) handles += b.toString(16).padStart(2, "0");
  if (expectHandles !== null && handles !== expectHandles)
    throw new PaintError(`access: cut for section handles ${handles}, not ${expectHandles}`);
  const access = readAccess(r);
  if (r.i !== bytes.length) throw new PaintError(`access: ${bytes.length - r.i} trailing bytes`);
  return access;
}

/** `flow-area/1`: the panel target area (km²) of each paint section, in sid order; `n` = paint.sectionCount. */
export function decodeFlowArea(bytes: Uint8Array, n: number): Float64Array {
  if (bytes[0] !== 0x42 || bytes[1] !== 0x43 || bytes[2] !== 0x46 || bytes[3] !== 0x41 || bytes[4] !== 1)
    throw new PaintError("flow-area: not a flow-area/1 file");
  const r = new Reader(bytes, 5), out = new Float64Array(n);
  for (let i = 0; i < n; i++) out[i] = r.uv() / 1000;
  if (r.i !== bytes.length) throw new PaintError("flow-area: its sections are not the paint's");
  return out;
}
